package com.hrflow.platform.config;
import com.hrflow.platform.user.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.ApplicationArguments; import org.springframework.boot.ApplicationRunner; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component public class InitialAdminConfig implements ApplicationRunner {private final UserRepository users;private final PasswordEncoder encoder;private final String email;private final String password; public InitialAdminConfig(UserRepository u,PasswordEncoder e,@Value("${INITIAL_ADMIN_EMAIL:}")String mail,@Value("${INITIAL_ADMIN_PASSWORD:}")String pass){users=u;encoder=e;email=mail;password=pass;} @Override @Transactional public void run(ApplicationArguments args){if(email.isBlank()||password.isBlank())return;if(password.length()<12)throw new IllegalStateException("INITIAL_ADMIN_PASSWORD must contain at least 12 characters");users.findByEmailIgnoreCase(email).orElseGet(()->{User u=new User();u.setEmail(email.trim().toLowerCase());u.setPasswordHash(encoder.encode(password));u.setRole(Role.ADMIN);u.setEnabled(true);u.setEmailVerified(true);return users.save(u);});}}
